import{z as l,x as s,o as B,c as d,q as A,j as r,D as t,d as E,s as i,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"报价策略与偏移","description":"","frontmatter":{"title":"报价策略与偏移","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/mm-quote-skew.md","filePath":"quant/mm-quote-skew.md","lastUpdated":1791063341000}'),p={name:"quant/mm-quote-skew.md"};function m(u,a,h,c,D,q){const n=s("Mermaid");return B(),d("div",null,[a[2]||(a[2]=A('<h1 id="报价策略与偏移" tabindex="-1">报价策略与偏移 <a class="header-anchor" href="#报价策略与偏移" aria-label="Permalink to &quot;报价策略与偏移&quot;">​</a></h1><div class="epigraph"><p>偏移不是把整对报价一起挪，而是围绕公允价不对称地移动两侧；锚错了，报价会追着自己的影子跑。</p><footer>—— 据 Avellaneda and Stoikov, Quantitative Finance, 2008；Guéant, Lehalle and Fernandez-Tapia, 2013 整理</footer></div><p><a href="/quant/mm-floor-to-practice">上一课</a>把参数缝填上：宽度与偏度两个旋钮有了点-in-time 的初值与灰度上线路径。本课把第二个旋钮单独拿出来。主干在<a href="/quant/inventory-skew">库存偏度</a>已把「中点平移改变成交方向概率」讲成交易台对象；<a href="/quant/avellaneda-stoikov">Avellaneda–Stoikov</a> 给出偏移随库存线性的一阶近似。本课写工程口径：锚在哪、偏多少、几股偏移同时到场时听谁的。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>偏移是围绕公允价不对称地移动买、卖两侧：多头时买价退远、卖价贴近，让下一笔更可能是卖。缺口有三个：<strong>锚</strong>（相对什么偏）、<strong>幅度</strong>（每单位库存偏多少）、<strong>覆盖顺序</strong>（库存、毒性、短期 alpha 各自要偏时如何叠加）。锚错了会自我循环：用自己的买卖价中点当公允价，偏移改动中点，中点又喂给偏度，报价越走越偏。幅度错了有两种对称的死法：偏得太小，库存像随机游走一直积到限额墙；偏得太大，一侧几乎不再成交，做市退化成单向减仓，价差收入消失。</p><h3 id="锚必须独立于自身-bbo" tabindex="-1">锚必须独立于自身 BBO <a class="header-anchor" href="#锚必须独立于自身-bbo" aria-label="Permalink to &quot;锚必须独立于自身 BBO&quot;">​</a></h3><p>可用的锚：多场所加权中点、深度加权的公允价、对冲腿价格加基差换算。判据只有一条：把你自己全部撤单之后，这个锚仍然存在。幅度取线性 \\(b\\cdot q\\)，\\(b\\) 的量纲是价格每风险单位，理论原型是 GLFT 价值函数的库存差分 \\(\\theta(q)-\\theta(q-1)\\)；靠近限额时按非线性放大，并设上限截断。</p><p><span class="marginnote">「偏移」翻译成大白话：不是把买卖两档报价一起挪，而是围绕公允价一退一进——手里囤了货，就把「让你继续进货的那一侧」退远、「帮你出货的那一侧」贴近，用价格引导对手更可能从你手里把货买走。它管的是下一笔成交的<strong>方向</strong>，不是成交的<strong>多少</strong>。</span></p><p><span class="marginnote">数字实例：\\(b=0.0002\\) 美元/股、净库存 \\(q=+1000\\) 股时，目标偏移 \\(b\\cdot q=0.20\\) 元。若半价差是 \\(0.30\\) 元，整对报价下移 \\(0.20\\) 在盘面上的效果是：卖价离中点只剩 \\(0.10\\)、买价退到 \\(0.50\\) 之外——卖侧更容易被击中，下一笔更可能是减仓的卖出。代入一次数字，「每单位库存偏多少」就不再是抽象系数。</span></p><p><span class="marginnote">常见错误是把锚放在「上一笔成交价」或自身 BBO 中点：成交价带着库存污染，自身报价又直接决定中点，两种锚都让偏度正反馈，盘面上表现为报价单边漂移、回不来的库存。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>叠加顺序写成规则而不是拍脑袋：毒性覆盖先于库存偏度——<a href="/quant/toxic-flow">毒性流</a>讲过，为了回归库存而向知情流继续供货，是把偏度用错了方向；短期 alpha 在存货之上叠加，偏移不再是「减仓」而是「抢先」，口径见 <a href="/quant/cartea-jaimungal">Cartea–Jaimungal</a>；最后才是库存项。每条来源各自给出目标偏移，引擎按优先级合成并限幅。</p><p>改价要节流：合成偏移的变化小于半 tick 不动单。价格-时间优先下每次改价通常丧失队列位置，见 <a href="/quant/cancel-queue-position">撤单、改单与队列位置</a>；为半 tick 的偏移精度白扔队列资本，是新手最常见的隐性成本。落到 tick 网格时，取整方向应朝减仓一侧（保守侧），否则一半偏移被网格吃掉。</p>',13)),(B(),r(o,null,{default:t(()=>[i(n,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20FAIR%5B%22%E7%8B%AC%E7%AB%8B%E5%85%AC%E5%85%81%E4%BB%B7%E9%94%9A%22%5D%20--%3E%20SKEW%5B%22%E5%90%88%E6%88%90%E5%81%8F%E5%BA%A6%22%5D%0A%20%20Q%5B%22%E5%87%80%E5%BA%93%E5%AD%98%20q%22%5D%20--%3E%20SKEW%0A%20%20TOX%5B%22%E6%AF%92%E6%80%A7%E7%8A%B6%E6%80%81%22%5D%20--%3E%7C%22%E8%A6%86%E7%9B%96%22%7C%20SKEW%0A%20%20A%5B%22%E7%9F%AD%E6%9C%9F%20alpha%22%5D%20--%3E%7C%22%E5%8F%A0%E5%8A%A0%22%7C%20SKEW%0A%20%20SKEW%20--%3E%20GRID%5B%22tick%20%E7%BD%91%E6%A0%BC%E5%8F%96%E6%95%B4%EF%BC%8C%E4%BF%9D%E5%AE%88%E4%BE%A7%22%5D%0A%20%20GRID%20--%3E%20BID%5B%22%E4%B9%B0%E4%BB%B7%EF%BC%9A%E9%94%9A%20%E2%88%92%20%CE%B4%E1%B5%87%20%2B%20%E5%81%8F%E7%A7%BB%22%5D%0A%20%20GRID%20--%3E%20ASK%5B%22%E5%8D%96%E4%BB%B7%EF%BC%9A%E9%94%9A%20%2B%20%CE%B4%E1%B5%83%20%2B%20%E5%81%8F%E7%A7%BB%22%5D%0A%20%20BID%20--%3E%20FILL%5B%22%E6%88%90%E4%BA%A4%22%5D%0A%20%20ASK%20--%3E%20FILL%0A%20%20FILL%20--%3E%20Q%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[E("偏度把成交方向概率写成库存的函数：偏移量 \\(b\\cdot q\\) 改变两侧被击中的相对强度，库存成为均值回复的受控跳过程，回复速度由 \\(b\\) 与成交强度共同决定。这意味着偏度是"),e("strong",null,"漂移控制"),E("，宽度是"),e("strong",null,"波动控制"),E("：只加宽价差不改变库存漂移，只平移则在价差收入大致不变时降低风险——两个旋钮分工，见"),e("a",{href:"/quant/inventory-skew"},"库存偏度"),E("的工程表述。把偏度当宽度用（库存危险就全面加价差），库存不动、收入先掉。")],-1)),(B(),r(o,null,{default:t(()=>[i(n,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E5%87%80%E5%BA%93%E5%AD%98%20q%20%E5%A4%A7%E4%BA%8E%200%22%5D%20--%3E%20SHIFT%5B%22%E6%95%B4%E5%AF%B9%E6%8A%A5%E4%BB%B7%E7%BB%95%E7%8B%AC%E7%AB%8B%E9%94%9A%E5%B9%B3%E7%A7%BB%20b%C2%B7q%22%5D%0A%20%20SHIFT%20--%3E%20BID%5B%22%E4%B9%B0%E4%BB%B7%E7%9B%B8%E5%AF%B9%E4%B8%AD%E7%82%B9%E9%80%80%E8%BF%9C%22%5D%0A%20%20SHIFT%20--%3E%20ASK%5B%22%E5%8D%96%E4%BB%B7%E7%9B%B8%E5%AF%B9%E4%B8%AD%E7%82%B9%E8%B4%B4%E8%BF%91%22%5D%0A%20%20BID%20--%3E%20PB%5B%22%E8%A2%AB%E4%B9%B0%E5%85%A5%E7%9A%84%E6%A6%82%E7%8E%87%E4%B8%8B%E9%99%8D%22%5D%0A%20%20ASK%20--%3E%20PA%5B%22%E8%A2%AB%E5%8D%96%E5%87%BA%E7%9A%84%E6%A6%82%E7%8E%87%E4%B8%8A%E5%8D%87%22%5D%0A%20%20PB%20--%3E%20DRIFT%5B%22%E5%BA%93%E5%AD%98%E6%BC%82%E7%A7%BB%E5%90%91%E4%B8%8B%EF%BC%9A%E5%81%8F%E5%BA%A6%E7%AE%A1%E6%96%B9%E5%90%91%22%5D%0A%20%20PA%20--%3E%20DRIFT%0A%20%20DRIFT%20--%3E%20COMP%5B%22%E5%AF%B9%E7%85%A7%EF%BC%9A%E5%8A%A0%E5%AE%BD%E4%BB%B7%E5%B7%AE%E6%98%AF%E4%B8%A4%E4%BE%A7%E5%90%8C%E9%80%80%EF%BC%8C%E6%88%90%E4%BA%A4%E4%B8%8E%E5%87%8F%E4%BB%93%E4%B8%80%E8%B5%B7%E6%8E%89%E2%80%94%E2%80%94%E5%AE%BD%E5%BA%A6%E7%AE%A1%E6%B3%A2%E5%8A%A8%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=A('<p><span class="marginnote">常见误区：初学者容易把偏度当宽度用——库存一危险就把双边价差全面加宽。加宽是两侧一起退，减仓概率和成交概率一起掉：库存没动，价差收入先没了。偏度是「一退一进」，靠不对称把库存漂移掰回来；宽度管的是波动暴露，两个旋钮拧错，会同时丢掉收入和风控。</span></p><p>偏度的极限不是无限偏移而是动作切换：库存贴近限额时，偏度非线性放大直到一侧退出，那是第六课限额的边界条件；毒性高到价差覆盖不了期望损失时，正确动作是停报一侧而不是继续偏——那是第七课降风险阶梯的起点。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>偏度不是毒性防御：知情流专挑你库存错误的一侧成交，线性偏度可能恰好加码亏损。tick 极小的品种偏移被费用主导，每笔报价的经济价差要按 <a href="/quant/maker-taker">maker-taker</a> 调整后再谈偏移。对冲腿在场时，\\(q\\) 必须是净风险单位而不是现货股数——对已中性簿再偏一次，是下一课对冲要解决的配对错误。偏移系数 \\(b\\) 不是常数：波动体制切换时 \\(b\\) 应随 \\(\\sigma^2\\) 走，这是第一课日历调度的对象。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>偏移是围绕独立公允价的不对称移动；锚必须独立于自身报价，否则正反馈。</li><li>幅度取 \\(b\\cdot q\\) 的线性原型，限额附近非线性放大，上限截断。</li><li>叠加有顺序：毒性覆盖、alpha 叠加、库存兜底；改价节流在半 tick。</li><li>偏度管漂移，宽度管波动；两个旋钮不可互相代替。</li><li>偏度的极限是动作切换：一侧退出或停报属于限额与降风险的口径。</li><li>出处：Avellaneda and Stoikov, <em>Quantitative Finance</em>, 2008；Guéant, Lehalle and Fernandez-Tapia, <em>Mathematics and Financial Economics</em>, 2013；Cartea, Jaimungal and Penalva, <em>Algorithmic and High-Frequency Trading</em>, 2015。</li></ul>',6))])}const k=l(p,[["render",m]]);export{f as __pageData,k as default};
